def semver_sort(versions):
    def parse_version(v):
        # Split by + to remove build metadata
        v_without_build = v.split('+')[0]

        # Split by - to separate core version and pre-release
        if '-' in v_without_build:
            core_part, prerelease_part = v_without_build.split('-', 1)
        else:
            core_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease_part:
            identifiers = prerelease_part.split('.')
            for identifier in identifiers:
                # Check if all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(v):
        major, minor, patch, prerelease = parse_version(v)
        # Pre-release versions sort before release versions
        # If no pre-release, we use empty tuple which sorts after non-empty
        # So we need: (major, minor, patch, has_prerelease, prerelease_identifiers)
        has_prerelease = 0 if prerelease else 1
        return (major, minor, patch, has_prerelease, prerelease)

    return sorted(versions, key=compare_key)

